from collections import Counter
def comps(g):
    g=np.array(g); H,W=g.shape
    seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; comp=[]
                while stack:
                    y,x=stack.pop(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and g[ny,nx]!=g[r,c]:
                            seen[ny,nx]=True; stack.append((ny,nx))
                out.append(comp)
    return out
