def f(g):
    bg=max(set(x for r in g for x in r), key=lambda v:sum(r.count(v) for r in g))
    H,W=len(g),len(g[0])
    # find rect: largest connected non-bg region of a single color != bg? use bounding box of most common non-bg color that forms hollow rect
    from collections import Counter
    cnt=Counter(x for r in g for x in r if x!=bg)
    col=cnt.most_common(1)[0][0]
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==col]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    h,w=r1-r0+1,c1-c0+1
    out=[row[:] for row in g]
    # clear interior
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            out[r][c]=bg
    # object = all non-bg cells outside the rect
    obj=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=bg and not(r0<=r<=r1 and c0<=c<=c1):
                obj.append((r,c,v))
    ors=[p[0] for p in obj]; ocs=[p[1] for p in obj]
    oh,ow=max(ors)-min(ors)+1,max(ocs)-min(ocs)+1
    for i,rw in enumerate(obj):
        pass
    for i in range(oh):
        for j in range(ow):
            v=next(p[2] for p in obj if p[0]-min(ors)==i and p[1]-min(ocs)==j)
            for dr in range(2):
                for dc in range(2):
                    rr,cc=r0+1+i*2+dr,c0+1+j*2+dc
                    if 0<=rr<len(out) and 0<=cc<len(out[0]):
                        out[rr][cc]=v
    return out
